// Zero-Trust & Anti-Spam Honeypot Verification
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// 1. Zero-Trust Check: Host/IP filtering
const clientIp = headers['x-forwarded-for'] || headers['x-real-ip'] || '127.0.0.1';
const xSource = headers['x-source'] || '';
const isLocal = clientIp.includes('127.0.0.1') || clientIp.includes('localhost') || clientIp === '::1' || xSource === 'arbizu-labs-internal';

if (!isLocal) {
  throw new Error('SECURITY VIOLATION: Solicitud rechazada. Ingress permitido exclusivamente desde localhost/127.0.0.1.');
}

// 2. Honeypot Check
if (body.bot_field || body.b_company_url) {
  return []; // Descartar silenciosamente spam bots
}

return [{
  json: {
    id: body.id || `lead_${Date.now()}`,
    timestamp: body.timestamp || new Date().toISOString(),
    name: body.name || 'Sin nombre',
    email: body.email || 'N/A',
    company: body.company || 'N/A',
    services: body.services || ['Consultoría General'],
    message: body.message || 'Sin mensaje detallado',
    total: body.total || 0
  }
}];

