parameters.jsCode:
const prev = $('zero-trust-filter').first().json;
const aiRaw = $input.first().json;

let scoreData = {
  score: 85,
  priority: 'ALTA',
  budget_tier: 'ENTERPRISE',
  tech_summary: 'Consulta directa de ingeniería de software / arquitectura B2B',
  suggested_action: 'Contactar vía WhatsApp o Email dentro de las próximas 4 horas.'
};

if (aiRaw && aiRaw.response) {
  try {
    const cleaned = aiRaw.response.replace(/```json/g, '').replace(/```/g, '').trim();
    scoreData = JSON.parse(cleaned);
  } catch (e) {
    // Usar defaults estructurados si el LLM no envió JSON estricto
  }
}

return [{
  json: {
    ...prev,
    qualification: scoreData
  }
}];

